 1	//power -- Stephanie Renee McIntyre
 2	//Based on the code used in the course overheads for Fall 2018
 3	
 4	//There is no definition for power, so this function will be used for validating that our imperative program is correct.
 5	function power(a: int, n: int): int //function for a to the power of n
 6	  requires 0 <= a
 7	  decreases n;{if (n == 0) then 1 else a * power(a, n - 1)}
 8	
 9	//Our code from class
10	method compute_power(a: int, n: int) returns (s: int)
11	/*Pre-Condition*/   requires n >= 0 && a >= 0;
12	/*Post-Condition*/  ensures s == power(a,n);
13	{
14	  /* (| a >= 0 ^ n >= 0 |)                - Pre-Condition: requires statement above */
15	  /* (| 1 = power(a,0) ^ 0<=n |)          - implied (a) */   assert 1 == power(a,0) && 0<=n;
16	  s := 1;
17	  /* (| s = power(a,0) ^ 0<=n |)          - assignment */    assert s == power(a,0) && 0<=n;
18	  var i := 0; 
19	  /* (| s = power(a,i) ^ i<=n |)          - assignment */    assert s == power(a,i) && i<=n;
20	  while (i < n)
21	  invariant s==power(a,i) && i<=n;
22	  decreases n-i;                          //this is the variant
23	  {
24	    /* (| s = power(a,i) ^ i<=n ^ i<n |)  - partial-while */ assert s == power(a,i) && i<=n && i<n;
25	    /* (| s*a = power(a,i+1) ^ i+1<=n |)  - implied (b) */   assert s*a == power(a,i+1) && i+1<=n;
26	    s := s*a;
27	    /* (| s = power(a,i+1) ^ i+1<=n |)    - assignment */    assert s == power(a,i+1) && i+1<=n;
28	    i := i+1;
29	    /* (| s = power(a,i) ^ i<=n |)        - assignment */    assert s == power(a,i) && i<=n;
30	  }
31	  /* (| s = power(a,i) ^ i<=n ^ -(i<n) |) - partial-while */ assert s == power(a,i) && i<=n && !(i<n);
32	  /* (| s = power(a,n) |)                 - implied (c) //Post-Condition: ensures statement above */
33	}
34	
35	/* Proof of implied (a): Follows from definition of the power function. */
36	
37	/* Proof of implied (b): Details left as exercise, but this is relatively simple. */
38	
39	/* Proof of implied (c): Simple substitution and uses the fact that i=n. */
40	
41	/* Proof of termination: the loop guard gives us the expression i<n. This is equivalent to n-i>=0.
42	   Prior to the loop, n>=0 and i=0.
43	   Each iteration of the loop, i increases by 1 and thus n-i decreases by 1. Thus n-i will eventually reach 0.
44	   When the n-i=0, n=i and thus the loop guard ends the loop as it is no longer the case that i<n.
45	   Thus the program terminates.
46	*/
47

